/* ==== options/i18n-apply.js ==== */
/**
 * M-4 (фаза 3): i18n-фундамент — общий механизм подстановки локализованных строк.
 *
 * Подключается в options/options.html, print/print.html, privacy/privacy.html
 * (M-4.4) и docs/index.html (M-4.4). Статическая разметка объявляет ключи из
 * _locales/<lang>/messages.json атрибутами:
 *   data-i18n              → textContent
 *   data-i18n-placeholder  → placeholder
 *   data-i18n-title        → title
 *   data-i18n-aria-label   → aria-label
 *   data-i18n-alt          → alt (M-4.4)
 *
 * Русский текст/значение в разметке остаётся ФОЛБЭКОМ: подстановка затирает его
 * только при непустом chrome.i18n.getMessage(key). Так страница остаётся читаемой,
 * если chrome.i18n недоступен (jsdom, отладочный контекст), и статические пины
 * регрессии по разметке не меняются.
 *
 * M-4.4: вне контекста расширения (docs/index.html на GitHub Pages) chrome.i18n
 * отсутствует — guard aiCmI18nAvailable() молча оставляет русский фолбэк, без
 * исключений и записей в консоль.
 *
 * Осознанно НЕ переводятся (M-4, п.5): логи, статусы и прочие динамические строки,
 * которые пишут options.js / print.js / content-скрипты.
 */
(function () {
  'use strict';

  // Атрибут-ключ → куда подставлять сообщение локали.
  var BINDINGS = [
    { key: 'data-i18n', target: 'textContent' },
    { key: 'data-i18n-placeholder', target: 'placeholder' },
    { key: 'data-i18n-title', target: 'title' },
    { key: 'data-i18n-aria-label', target: 'aria-label' },
    // M-4.4: alt скриншотов руководства и карточек документации.
    { key: 'data-i18n-alt', target: 'alt' }
  ];

  /**
   * M-4.4: доступен ли контекст расширения (chrome.i18n). Вне расширения —
   * docs/index.html на GitHub Pages — возвращает false, и подстановка не делается:
   * страница молча остаётся на русском тексте разметки.
   */
  function aiCmI18nAvailable() {
    return typeof chrome !== 'undefined' && !!chrome.i18n && typeof chrome.i18n.getMessage === 'function';
  }

  /**
   * Сообщение локали по ключу. '' — если chrome.i18n недоступен, ключ неизвестен
   * или вызов бросил: вызывающая сторона сохраняет фолбэк из разметки.
   */
  function aiCmI18nMessage(key) {
    try {
      if (aiCmI18nAvailable()) {
        return chrome.i18n.getMessage(key) || '';
      }
    } catch (eMessage) { return ''; }
    return '';
  }

  /**
   * Подставляет локализованные строки во всё поддерево root (по умолчанию document).
   * Возвращает число фактически применённых подстановок. Идемпотентно.
   */
  function aiCmI18nApply(root) {
    var scope = root || (typeof document !== 'undefined' ? document : null);
    if (!scope || typeof scope.querySelectorAll !== 'function') return 0;
    var applied = 0;
    for (var i = 0; i < BINDINGS.length; i++) {
      var binding = BINDINGS[i];
      var nodes = scope.querySelectorAll('[' + binding.key + ']');
      for (var j = 0; j < nodes.length; j++) {
        var message = aiCmI18nMessage(nodes[j].getAttribute(binding.key));
        if (!message) continue;
        if (binding.target === 'textContent') nodes[j].textContent = message;
        else nodes[j].setAttribute(binding.target, message);
        applied++;
      }
    }
    return applied;
  }

  function aiCmI18nBoot() {
    // Вне расширения подстановка не запускается вовсе: текст разметки остаётся ru.
    if (!aiCmI18nAvailable()) return;
    aiCmI18nApply(document);
  }

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', aiCmI18nBoot);
    } else {
      aiCmI18nBoot();
    }
  }

  // Экспорт для юнит-тестов (jest). В браузере (MV3, классический скрипт
  // options.html/print.html/privacy.html/docs/index.html) module не определён —
  // блок не выполняется.
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
      aiCmI18nApply: aiCmI18nApply,
      aiCmI18nMessage: aiCmI18nMessage,
      aiCmI18nAvailable: aiCmI18nAvailable,
      bindings: BINDINGS
    };
  }
})();

/* ==== utils/markdown.js ==== */
/**
 * Лёгкий markdown в HTML конвертер для печатной формы (экспорт PDF).
 * Чистая логика, без зависимостей от DOM или браузера:
 *   - работает в браузере (window.MarkdownRenderer) и в Node (module.exports).
 *
 * Поддерживает: заголовки от H1 до H6, жирный (двойные звёздочки), курсив
 * (одинарные звёздочки или подчёркивания), инлайн-код, ссылки [text](url),
 * списки (в том числе строки вида "- Метка: текст"), markdown-таблицы
 * (строки с разделителем) и code-ограждения из трёх обратных кавычек.
 * Остальной текст экранируется: HTML не проходит. Кириллица не страдает.
 */

(function () {
  'use strict';

  function escapeHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&' + 'amp;')
      .replace(/</g, '&' + 'lt;')
      .replace(/>/g, '&' + 'gt;')
      .replace(/"/g, '&' + 'quot;');
  }

  // Инлайн-разметка: инлайн-код, жирный, курсив, ссылки.
  // Работает на уже экранированной строке (HTML не может пролезть внутрь).
  function inline(text) {
    var src = escapeHtml(text);
    return src.replace(
      /(`[^`\n]+`)|(\*{2}[^*\n]+\*{2})|(\*[^*\s\n][^*\n]*\*)|(_[^_\s\n][^_\n]*_)|(\[[^\]]+\]\(([^)\s]+)\))/g,
      function (m, code, bold, italic, underline, link, url) {
        if (code) return '<code>' + code.slice(1, -1) + '</code>';
        if (bold) return '<strong>' + bold.slice(2, -2) + '</strong>';
        if (italic) return '<em>' + italic.slice(1, -1) + '</em>';
        if (underline) return '<em>' + underline.slice(1, -1) + '</em>';
        if (link) {
          var u = String(url || '').trim();
          // Только безопасные протоколы
          if (/^(https?:|mailto:|#|\/)/i.test(u)) {
            var label = link.slice(1, link.indexOf(']('));
            return '<a href="' + escapeHtml(u) + '">' + label + '</a>';
          }
          return m;
        }
        return m;
      }
    );
  }

  // Строка-разделитель таблицы: только | - : и пробелы, содержит хотя бы один минус
  function isTableSeparator(line) {
    if (!line) return false;
    var c = line.charAt(0);
    if (c !== '|' && c !== '-' && c !== ':') return false;
    return /^[\s|:—-]+$/.test(line) && /-/.test(line);
  }

  function parseRow(line, tag) {
    var s = String(line || '').trim();
    if (s.charAt(0) === '|') s = s.slice(1);
    if (s.charAt(s.length - 1) === '|') s = s.slice(0, -1);
    var cells = s.split('|');
    var out = '<tr>';
    for (var c = 0; c < cells.length; c++) {
      out += '<' + tag + '>' + inline(cells[c].trim()) + '</' + tag + '>';
    }
    return out + '</tr>';
  }

  // Собирает таблицу, начиная со строки lines[i] (содержит | и есть разделитель ниже).
  function renderTable(lines, i) {
    var head = parseRow(lines[i], 'th');
    var body = [];
    var j = i + 2; // пропускаем строку-разделитель
    while (j < lines.length) {
      var t = (lines[j] || '').trim();
      if (t === '' || t.indexOf('|') === -1) break;
      body.push(parseRow(lines[j], 'td'));
      j++;
    }
    return {
      html: '<table><thead>' + head + '</thead>' +
        (body.length ? '<tbody>' + body.join('') + '</tbody>' : '') + '</table>',
      nextIndex: j
    };
  }

  var LIST_RE = /^([-*+]|\d+[.)])\s+(.*)$/;
  var HEADING_RE = /^(#{1,6})\s+(.*)$/;
  var FENCE_RE = /^```/;

  function renderMarkdown(md) {
    if (typeof md !== 'string') return '';
    var lines = String(md).replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
    var out = [];
    var i = 0;
    while (i < lines.length) {
      var trimmed = (lines[i] || '').trim();

      // Code-ограждение
      if (FENCE_RE.test(trimmed)) {
        var lang = trimmed.slice(3).trim();
        var codeLines = [];
        i++;
        while (i < lines.length && !FENCE_RE.test((lines[i] || '').trim())) {
          codeLines.push(lines[i]);
          i++;
        }
        i++; // закрывающая строка с тремя кавычками
        out.push('<pre' + (lang ? ' data-lang="' + escapeHtml(lang) + '"' : '') + '>' +
          '<code>' + escapeHtml(codeLines.join('\n')) + '</code></pre>');
        continue;
      }

      // Заголовок
      var hm = trimmed.match(HEADING_RE);
      if (hm) {
        var level = hm[1].length;
        out.push('<h' + level + '>' + inline(hm[2]) + '</h' + level + '>');
        i++;
        continue;
      }

      // Таблица: строка начинается с | , следующая — разделитель
      if (trimmed.charAt(0) === '|' && isTableSeparator((lines[i + 1] || '').trim())) {
        var tbl = renderTable(lines, i);
        out.push(tbl.html);
        i = tbl.nextIndex;
        continue;
      }

      // Список (ul/ol), включая строки вида "- Метка: текст"
      var lm = trimmed.match(LIST_RE);
      if (lm) {
        var ordered = /\d+[.)]/.test(lm[1]);
        var tag = ordered ? 'ol' : 'ul';
        var items = [];
        while (i < lines.length) {
          var t2 = (lines[i] || '').trim();
          if (t2 === '') break;
          var m2 = t2.match(LIST_RE);
          if (!m2) break;
          items.push('<li>' + inline(m2[2]) + '</li>');
          i++;
        }
        out.push('<' + tag + '>' + items.join('') + '</' + tag + '>');
        continue;
      }

      // Пустая строка
      if (trimmed === '') { i++; continue; }

      // Параграф: собираем до пустой строки или начала нового блока
      var paraLines = [lines[i]];
      i++;
      while (i < lines.length) {
        var t3 = (lines[i] || '').trim();
        if (t3 === '') break;
        if (HEADING_RE.test(t3) || FENCE_RE.test(t3)) break;
        if (LIST_RE.test(t3)) break;
        if (t3.charAt(0) === '|' && isTableSeparator((lines[i + 1] || '').trim())) break;
        paraLines.push(lines[i]);
        i++;
      }
      out.push('<p>' + inline(paraLines.join('\n')) + '</p>');
    }
    return out.join('\n');
  }

  var MarkdownRenderer = {
    render: renderMarkdown,
    inline: inline,
    escapeHtml: escapeHtml
  };

  if (typeof module !== 'undefined' && module.exports) module.exports = MarkdownRenderer;
  if (typeof window !== 'undefined') window.MarkdownRenderer = MarkdownRenderer;
})();

/* ==== print/print.js ==== */
/**
 * Печатная форма для экспорта истории в PDF (v1.6.0).
 * Открывается из попапа кнопкой «Сохранить .pdf» как
 * chrome.tabs.create({ url: 'print/print.html?tab=<id>' }).
 *
 * Поток:
 *   1) читаем id вкладки из query-параметра tab;
 *   2) берём host этой вкладки (chrome.tabs.get);
 *   3) достаём санированный aiCmHistory из chrome.storage.local
 *      (тот же источник, что у индикатора и экспортов .md/.json);
 *   4) фильтруем запись по хосту вкладки и рендерим HTML;
 *   5) выставляем непустой document.title (имя файла в диалоге «Сохранить как PDF»)
 *      и вызываем window.print() — ровно ОДИН раз за жизненный цикл страницы;
 *      пользователь сохраняет PDF штатным диалогом Chrome.
 */

(function () {
  'use strict';

  // M-4.2: строки печатной формы берутся из _locales через chrome.i18n.getMessage
  // (ключи print_* есть и в ru, и в en). chrome.i18n недоступен (jsdom-песочница,
  // отладочный контекст) → возвращается прежний русский литерал: форма без локали
  // байтово прежняя. $1..$9 в сообщении локали подставляются substitutions.
  function aiCmI18nMessage(key, fallback, substitutions) {
    try {
      if (typeof chrome !== 'undefined' && chrome.i18n && typeof chrome.i18n.getMessage === 'function') {
        var message = substitutions ? chrome.i18n.getMessage(key, substitutions) : chrome.i18n.getMessage(key);
        if (message) return message;
      }
    } catch (eMessage) { return fallback; }
    return fallback;
  }

  var SITE_LABELS = {
    'chatgpt': 'ChatGPT',
    'gemini': 'Gemini',
    'aistudio': 'Google AI Studio',
    'google_search': 'Google Search AI',
    'deepseek': 'DeepSeek',
    'claude': 'Claude',
    'perplexity': 'Perplexity'
  };

  function getParam(name) {
    try { return new URLSearchParams(window.location.search).get(name); } catch (e) { return null; }
  }

  function pad2(n) { return (n < 10 ? '0' : '') + n; }
  function formatDateTime(ts) {
    var d = ts ? new Date(ts) : new Date();
    return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' +
      pad2(d.getHours()) + ':' + pad2(d.getMinutes());
  }

  // Шапка: платформа, модель, дата, токены.
  function buildHeader(history) {
    var h = history || {};
    var tokens = (typeof h.tokens === 'number') ? h.tokens : 0;
    var limit = (typeof h.limit === 'number') ? h.limit : 0;
    var percent = (typeof h.percent === 'number') ? h.percent : 0;
    var platform = SITE_LABELS[h.site] || h.site || 'AI Chat';

    var html = '<div class="doc-header">';
    html += '<h1>' + escapeText(aiCmI18nMessage('print_doc_title', 'AI Context Monitor — история диалога')) + '</h1>';
    html += '<div class="doc-meta">';
    html += '<b>' + escapeText(aiCmI18nMessage('print_meta_platform', 'Платформа:')) + '</b> ' + escapeText(platform) + '<br>';
    html += '<b>' + escapeText(aiCmI18nMessage('print_meta_model', 'Модель:')) + '</b> ' + escapeText(h.model || '—') + '<br>';
    html += '<b>' + escapeText(aiCmI18nMessage('print_meta_date', 'Дата:')) + '</b> ' + escapeText(formatDateTime(h.updatedAt)) + '<br>';
    html += '<b>' + escapeText(aiCmI18nMessage('print_meta_tokens', 'Токены:')) + '</b> ' + tokens.toLocaleString() + ' / ' + limit.toLocaleString() +
      ' (' + percent + '%)';
    html += '</div></div>';
    return html;
  }

  function buildMessages(messages) {
    var html = '';
    for (var i = 0; i < messages.length; i++) {
      var msg = messages[i] || {};
      var role = (msg.role === 'user') ? 'user' : 'assistant';
      var text = (typeof msg.text === 'string') ? msg.text : '';
      html += '<div class="msg-block ' + role + '">';
      // M-4.2: роль — ключ print_role_user / print_role_assistant (ru/en), не хардкод
      html += '<div class="msg-role">' + escapeText(role === 'user'
        ? aiCmI18nMessage('print_role_user', 'Пользователь')
        : aiCmI18nMessage('print_role_assistant', 'Ассистент')) + '</div>';
      html += '<div class="msg-body">' + renderMarkdown(text) + '</div>';
      html += '</div>';
    }
    return html;
  }

  function render(history) {
    var messages = (history && Array.isArray(history.messages)) ? history.messages : [];
    var header = buildHeader(history);
    var body = messages.length ? buildMessages(messages) :
      '<p>' + escapeText(aiCmI18nMessage('print_empty_body', 'История пуста: в хранилище нет сообщений для этой вкладки.')) + '</p>';
    return header + body;
  }

  function escapeText(s) {
    var md = (typeof window.MarkdownRenderer !== 'undefined' && window.MarkdownRenderer) ?
      window.MarkdownRenderer : null;
    if (md && md.escapeHtml) return md.escapeHtml(s);
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function renderMarkdown(text) {
    var md = (typeof window.MarkdownRenderer !== 'undefined' && window.MarkdownRenderer) ?
      window.MarkdownRenderer : null;
    if (md && md.render) return md.render(text);
    return escapeText(text);
  }

  function showEmpty() {
    // O-27/O-32 (диагностика): пустая форма — печати/файла не будет; имя файла пустое.
    printDiag('print-pdf-empty', { reason: 'history-not-found' });
    document.getElementById('print-content').innerHTML = '';
    document.getElementById('empty-state').style.display = 'block';
  }

  function showContent(history) {
    // O-27/O-32 (диагностика): база печатной формы (для строки точки печати) — только чтение.
    try {
      var msgsDiag = (history && Array.isArray(history.messages)) ? history.messages : [];
      var partsDiag = [];
      for (var miDiag = 0; miDiag < msgsDiag.length; miDiag++) {
        partsDiag.push((msgsDiag[miDiag] && msgsDiag[miDiag].text) || '');
      }
      diagBaseHead = partsDiag.join('\n');
      diagBaseConvId = (history && history.convId) || '';
      diagBaseSite = (history && history.site) || '';
      diagBaseMsgs = msgsDiag.length;
      printDiag('print-render', { reason: 'form-rendered' });
    } catch (eDiagShow) { diagBaseHead = ''; diagBaseConvId = ''; diagBaseSite = ''; diagBaseMsgs = 0; }
    document.getElementById('empty-state').style.display = 'none';
    document.getElementById('print-content').innerHTML = render(history);
  }

  function waitForRenderer(cb) {
    if (typeof window.MarkdownRenderer !== 'undefined' && window.MarkdownRenderer) {
      cb();
      return;
    }
    setTimeout(function () { waitForRenderer(cb); }, 30);
  }

  // Автозакрытие вкладки печати после сохранения PDF: диалог печати закрылся (afterprint)
  // или сработал фолбэк-таймаут 2с. Шлём фоновому SW запрос на закрытие вкладки.
  function scheduleClosePrintTab() {
    var sent = false;
    function send() {
      if (sent) return;
      sent = true;
      try { chrome.runtime.sendMessage({ type: 'close-print-tab' }); } catch (e) { printDiag('catch:print', { err: String(e) }); }
    }
    window.addEventListener('afterprint', send);
    setTimeout(send, 2000);
  }

  // v1.18 (E-2): гигиена печати.
  // (A) Диалог сохранения PDF берёт имя файла из document.title: пустой/слетевший title
  //     даёт пустое имя. Перед print() title выставляем ЯВНО из локали, с непустым фолбэком.
  // (B) Автопечать разрешена РОВНО ОДИН раз за жизненный цикл страницы: повторные вызовы
  //     (двойной init/повторная отрисовка) печати не запускают — иначе первый же сохранённый
  //     PDF оказывается «занят другим приложением» (Chrome перезаписывает файл вторым диалогом).
  // v1.18 (E-2) + M-4.2: title берётся из локали (print_page_title) с непустым
  // русским фолбэком для окружений без chrome.i18n.
  var PRINT_TITLE_FALLBACK = 'AI Context Monitor — печатная форма';
  var printInvoked = false;

  // ===========================================================================
  // O-27/O-32 (ДИАГНОСТИКА, только измерение): точка печати/сохранения PDF.
  // Гейт — aiCmDebug: sessionStorage 'aiCmDebug' === '1' ИЛИ чекбокс «Подробные логи»
  // (window.__aiCmDebugLogs). Имя файла в диалоге «Сохранить как PDF» — это document.title,
  // поэтому в лог идёт именно он (пустой — словом «пустое»), плюс первые 100 символов
  // базы, URL документа, convId и источник вызова. Поведение и разметка не меняются.
  // ===========================================================================
  var diagBaseHead = '';
  var diagBaseConvId = '';
  var diagBaseSite = '';
  var diagBaseMsgs = 0;
  function printDiagOn() {
    try {
      if (typeof sessionStorage !== 'undefined' && sessionStorage &&
        sessionStorage.getItem('aiCmDebug') === '1') return true;
    } catch (eSess) { return false; }
    try {
      if (typeof window !== 'undefined' && window && window.__aiCmDebugLogs === true) return true;
    } catch (eWin) { return false; }
    return false;
  }
  function printDiagStack() {
    try {
      var lines = String((new Error()).stack || '').split('\n');
      var out = [];
      for (var i = 1; i < lines.length && out.length < 4; i++) {
        var s = String(lines[i] || '').replace(/\s+/g, ' ').trim();
        if (!s || s.indexOf('printDiag') !== -1) continue;
        out.push(s);
      }
      return out.join(' <- ');
    } catch (eStack) { return ''; }
  }
  function printDiag(trigger, extra) {
    if (!printDiagOn()) return false;
    try {
      var url = '';
      try { url = String((typeof location !== 'undefined' && location && location.href) || ''); } catch (eUrl) { url = ''; }
      var title = '';
      try { title = String(document.title || ''); } catch (eTitle) { title = ''; }
      var head = String(diagBaseHead || '').replace(/\s+/g, ' ').trim();
      if (head.length > 100) head = head.slice(0, 100) + '…';
      console.log('[AI CM][diag] download trigger=' + trigger +
        ' file=' + (title || 'пустое') +
        ' bytes100=' + (head || '(пусто)') +
        ' len=' + String(diagBaseHead || '').length +
        ' url=' + url +
        ' threadId=(нет)' +
        ' convId=' + (diagBaseConvId || '(нет)') +
        ' site=' + (diagBaseSite || '') +
        ' msgs=' + diagBaseMsgs +
        ' reason=' + ((extra && extra.reason) || '') +
        ' src=' + printDiagStack());
    } catch (eDiag) { return false; }
    return true;
  }

  function ensurePrintTitle() {
    try {
      document.title = aiCmI18nMessage('print_page_title', PRINT_TITLE_FALLBACK);
    } catch (e) {
      document.title = PRINT_TITLE_FALLBACK;
    }
    return document.title;
  }

  function triggerPrint() {
    if (printInvoked) {
      // O-27/O-32 (диагностика): повторный триггер печати подавлен (E-2) — файла не будет.
      printDiag('print-pdf-suppressed', { reason: 'duplicate print suppressed (E-2)' });
      console.log('[AI CM][print] duplicate print suppressed');
      return false;
    }
    printInvoked = true;
    ensurePrintTitle();
    // O-27/O-32 (диагностика): точка печати/сохранения PDF — имя файла = document.title.
    printDiag('print-pdf', { reason: 'auto-print (window.print); user saves PDF' });
    scheduleClosePrintTab();
    window.print();
    return true;
  }

  function init() {
    var tabId = getParam('tab');
    if (!tabId) { showEmpty(); return; }

    chrome.tabs.get(parseInt(tabId, 10), function (tab) {
      var host = '';
      if (chrome.runtime.lastError) {
        // Вкладка могла закрыться — рендерим последнюю доступную запись без фильтра по хосту
        host = '';
      } else if (tab && tab.url) {
        try { host = new URL(tab.url).hostname; } catch (e) { host = ''; }
      }

      // v1.13.1: атрибуция ручного экспорта — снимок ТОЛЬКО текущего convId вкладки.
      // Спрашиваем content-скрипт вкладки; convId известен → рендерим текущий разговор
      // (даже если база ещё пуста → пустая форма, но НИКОГДА чужой convId).
      // convId нет / content-скрипт недоступен → прежний host-level фолбэк aiCmHistory.
      chrome.tabs.sendMessage(parseInt(tabId, 10), { type: 'aiCmExportCurrent' }, function (snapResp) {
        var snap = (snapResp && snapResp.data) ? snapResp.data : null;
        chrome.storage.local.get(['aiCmHistory'], function (data) {
          var history = null;
          var all = data && data.aiCmHistory ? data.aiCmHistory : null;
          if (snap && snap.convId) {
            history = snap;
          } else if (all && all.messages) {
            if (!host || all.host === host) history = all;
          }
          if (!history || !history.messages || !history.messages.length) { showEmpty(); return; }
          showContent(history);
          // Форма отрисована — диалог печати (пользователь выбирает «Сохранить как PDF»).
          setTimeout(function () {
            triggerPrint();
          }, 50);
        });
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', waitForRenderer.bind(null, init));
  } else {
    waitForRenderer(init);
  }

  // v1.18 (E-2): точка автопечати доступна тестам (регрессионный пин «ровно один print»).
  // Поведение страницы не меняется — init() вызывает ту же функцию.
  try { window.__aiCmPrintTrigger = triggerPrint; } catch (e) { console.warn('[AI CM][catch] print:', e); }
})();
